      var r = 55 + rnd(i + 90) * 14;
      var hgt = city ? 19 + rnd(i + 7) * 34 : 24 + rnd(i + 7) * 44;
      var w = city ? 3.2 + rnd(i + 21) * 4.6 : 5 + rnd(i + 21) * 7;
      var capH = city ? 5.5 + rnd(i + 33) * 4 : 9 + rnd(i + 33) * 8;
